INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0100', '俺だけレベルアップな件', '2024年冬', 'PR0001', 'TVシリーズ', 12, '『俺だけレベルアップな件』（おれだけレベルアップなけん、朝: 나 혼자만 레벨업、英: Solo Leveling）は、原作・原案Chugong、作画DUBU（REDICE STUDIO）による韓国の小説、漫画、ウェブトゥーン。日本語版は韓国語版とはストーリーやキャラクターに差異がある。略称は「나혼렙」「俺レベ」。', 151807) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0101', 'ダンジョン飯', '2024年冬', 'PR0002', 'TVシリーズ', 24, '『ダンジョン飯』（ダンジョンめし）は、九井諒子による日本の漫画作品。年10回刊漫画誌『ハルタ』（KADOKAWA）にてvolume11からvolume107まで連載。著者初の長編連載作品。', 153518) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0102', 'ようこそ実力至上主義の教室へ 3rd Season', '2024年冬', 'PR0003', 'TVシリーズ', 13, NULL, 146066) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0103', 'マッシュル-MASHLE- 神覚者候補選抜試験編', '2024年冬', 'PR0001', 'TVシリーズ', 12, NULL, 166610) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0104', 'ゆびさきと恋々', '2024年冬', 'PR0004', 'TVシリーズ', 12, '『ゆびさきと恋々』（ゆびさきとれんれん、英語: A Sign of Affection）は、森下suuによる日本の漫画作品。『デザート』（講談社）にて、2019年9月号から連載中。 2025年11月時点で世界累計部数は750万部を突破している。', 166794) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0105', '治癒魔法の間違った使い方', '2024年冬', 'PR0005', 'TVシリーズ', 13, NULL, 137908) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0106', '月が導く異世界道中 第二幕', '2024年冬', 'PR0006', 'TVシリーズ', 25, NULL, 139518) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0107', '魔都精兵のスレイブ', '2024年冬', 'PR0007', 'TVシリーズ', 12, '『魔都精兵のスレイブ』（まとせいへいのスレイブ）は、原作：タカヒロ、作画：竹村洋平による日本の漫画作品。集英社のウェブコミック配信サイト『少年ジャンプ+』にて2019年1月5日より土曜日に配信中。カバーイラストの彩色はOKADAが担当。2023年1月時点における電子版を含めた単行本の累計発行部数は400万部を突破している。', 141821) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0108', '僕の心のヤバイやつ 第2期', '2024年冬', 'PR0005', 'TVシリーズ', 13, NULL, 166216) ON CONFLICT DO NOTHING;
