INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0144', 'クラスの大嫌いな女子と結婚することになった。', '2025年冬', 'PR0035', 'TVシリーズ', 12, '『クラスの大嫌いな女子と結婚することになった。』（クラスのだいきらいなじょしとけっこんすることになった）は、天乃聖樹による日本のYouTube漫画およびそれを原作としたメディアミックス作品。略称は「クラコン」。イラストはもすこんぶが担当している。2026年4月時点で電子版を含めたシリーズ累計部数は72万部を突破している。 2020年3月からYouTube動画として投稿されていた本作がメディアミック', 178462) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0145', '全修。', '2025年冬', 'PR0036', 'TVシリーズ', 12, '『全修。』（ぜんしゅう。）は、MAPPA制作による日本のテレビアニメ作品。2025年1月から3月まで、テレビ東京系列ほかにて放送された。アニメ業界を舞台とするオリジナルアニメ作品であり、タイトルは「オールリテイク」を意味するアニメ業界用語から取られている。', 176273) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0146', 'ギルドの受付嬢ですが、残業は嫌なのでボスをソロ討伐しようと思います', '2025年冬', 'PR0012', 'TVシリーズ', 12, '『ギルドの受付嬢ですが、残業は嫌なのでボスをソロ討伐しようと思います』（ギルドのうけつけじょうですが、ざんぎょうはいやなのでボスをソロとうばつしようとおもいます）は、香坂マトによる日本のライトノベル。電撃文庫（KADOKAWA）より2021年3月から刊行されている。2023年8月時点で電子版を含めたシリーズ累計部数は30万部を突破している。公式略称は「ギルます」。 イラストはがおうが担当していたが', 167143) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0147', 'ハニーレモンソーダ', '2025年冬', 'PR0006', 'TVシリーズ', 12, '『ハニーレモンソーダ』（Honey Lemon Soda）は、村田真優による日本の漫画。『りぼん』（集英社）にて、2016年2月号から2026年5月号まで連載された。 クラスの人気者であるレモン色の髪の男子高校生と、いじめられた過去を持つ女子高生の恋愛模様を描く。 『セブンティーン』（集英社）2020年9月号の「読者が選ぶ好きな少女マンガ&実写化してほしいマンガランキング」において1位を記録した。', 175443) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0148', 'わたしの幸せな結婚 第二期', '2025年冬', 'PR0037', 'TVシリーズ', 13, NULL, 169441) ON CONFLICT DO NOTHING;
