INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0150', '炎炎ノ消防隊 参ノ章', '2025年春', 'PR0039', 'TVシリーズ', 12, NULL, 149118) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0151', 'ラザロ', '2025年春', 'PR0036', 'TVシリーズ', 13, 'ラザロ（古代ギリシア語: Λάζαρος、ラテン語: Lazarus）は、ユダヤ人の男性で、イエス・キリストの友人。『ヨハネによる福音書』に語られる、イエスによって死から甦る『ラザロの復活』の逸話によって著名な人物である。日本ハリストス正教会ではラザリと転写される。ラザロという名はユダヤ名・エルアザルがギリシア語化した名と推測される。 なお、「金持ちとラザロ」で知られるラザロが『ルカによる福音書』', 167336) ON CONFLICT DO NOTHING;
