INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000100', 'AN0100', '성진우', 'Class: Mage Relative(s): Park Kyung-Hye (Mother), Sung Jin-Ah (Sister), ~!Sung Il-Hwan (Father), Cha Hae-In (Wife), Sung Su-Ho (Son), Yoo Jin-Ho (Brother in Law)!~  ~!Guild: Ahjin Guild (Guild Master)', 23, 'Male', 129928) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000101', 'AN0100', '백윤호', 'He is a S rank hunter and master of the White Tiger guild.', NULL, 'Male', 136077) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000102', 'AN0100', '송치율', 'Magic Type: Fire  Korean C-Rank Hunter and kumdo teacher. He is also one of Jinwoo''s old friends, having known him since he was a E-Rank Hunter.', NULL, 'Male', 136073) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000103', 'AN0100', '강정호', NULL, NULL, NULL, 323589) ON CONFLICT DO NOTHING;
