INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000105', 'AN0101', 'ライオス・トーデン', 'Height: 185 cm (6''1")  Laios is the leader of his party and Falin''s older brother. He is a tall-man from the Northern Continent.  Laios is a monster fanatic and a strong fighter. His deep knowledge an', 26, 'Male', 126818) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000106', 'AN0101', 'マルシル・ドナトー', 'Height: 160 cm (5''3")  Marcille is mage who is part of Laios'' party. She is an elf from the Northern Continent.  ~!She is actually half-elf and half tall-man. Her mother is an elf, and father was a ta', 50, 'Female', 127292) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000107', 'AN0101', 'センシ', 'Height: 140 cm (4''7")  Senshi is a member of Laios'' party. He is a dwarf from the Eastern Continent.  Having spent 10 years studying monster cuisine and living a self-sufficient life inside the dungeo', 112, 'Male', 127689) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000108', 'AN0101', 'チルチャック・ティムズ', 'Height: 110 cm (3''7")  Chilchuck is a member of Laios'' party. He is a half-foot from the Eastern Continent.  Chilchuck is shrewd, practical, and sharp-tongued. He refuses to take jobs unless he is pai', 29, 'Male', 130509) ON CONFLICT DO NOTHING;
